svg.script:
// LuminSDK only works when the app document descends from a real http(s) origin.
// Measured: served over http every container works (srcdoc, about:blank, blob —
// even with origin "null"); opened from file:// none do, and no shim fixes that,
// because a local file cannot produce an http origin. N3ptune.bat serves this
// folder for exactly that reason — so when we are on file://, look for it first
// and hand over. Nothing else about the launcher changes.
async function localServer(){
    if (location.protocol !== "file:") return null;
    for (const port of [8777, 8778, 8779, 8780]) {
        const url = "http://127.0.0.1:" + port + "/n3ptune-v2.html";
        try {
            // no-cors: we only care that something answered, not what it said.
            await Promise.race([
                fetch(url, { mode: "no-cors", cache: "no-store" }),
                new Promise((_, rej) => setTimeout(() => rej(new Error("timeout")), 1200))
            ]);
            return url;
        } catch (e) { /* nothing on that port — try the next */ }
    }
    return null;
}

(async () => {
    const st = document.getElementById("st");
    try {
        const local = await localServer();
        if (local) {
            st.textContent = "Starting…";
            location.replace(local);      // real origin: all four sources work
            return;
        }

        const url = "https://cdn.jsdelivr.net/gh/groffstock/N3ptune-v2@main/n3ptune-v2.html";

        const response = await fetch(url, {
            cache: "no-store"
        });

        if (!response.ok) {
            throw new Error("HTTP " + response.status);
        }

        const html = await response.text();

        // Safety net for contexts with no usable storage (opaque origins, private
        // mode). The app reads sessionStorage on the FIRST line of its passcode-gate
        // script, so a throw there means pcAdd/submitKey never get defined and the
        // keypad ignores every tap. Only kicks in when the real thing is unreachable.
        const shim = '<script>(function(){function ok(n){try{var s=window[n];s.setItem("__p","1");s.removeItem("__p");return true}catch(e){return false}}' +
            'function mem(){var d={};return{getItem:function(k){return Object.prototype.hasOwnProperty.call(d,k)?d[k]:null},' +
            'setItem:function(k,v){d[k]=String(v)},removeItem:function(k){delete d[k]},clear:function(){d={}},' +
            'key:function(i){return Object.keys(d)[i]||null},get length(){return Object.keys(d).length}}}' +
            '["localStorage","sessionStorage"].forEach(function(n){if(!ok(n)){try{Object.defineProperty(window,n,{value:mem(),configurable:true})}catch(e){}}})})();<\/script>';

        const patched = /<head[^>]*>/i.test(html)
            ? html.replace(/<head[^>]*>/i, function(m){ return m + shim })
            : shim + html;

        // Run the fetched HTML INSIDE this document rather than navigating to a
        // blob: URL. A blob built by a file:// page lands on an opaque, INSECURE
        // origin: no localStorage/sessionStorage, and no crypto.randomUUID or
        // crypto.subtle — so games die on "crypto.randomUUID is not a function".
        // A srcdoc iframe inherits this document's context instead, staying a
        // secure context with working storage on file:// and http(s) alike.
        const svg = document.documentElement;
        svg.removeAttribute("viewBox");                 // 1 user unit == 1 CSS px

        const fo = document.createElementNS("http://www.w3.org/2000/svg", "foreignObject");
        fo.setAttribute("x", "0"); fo.setAttribute("y", "0");
        fo.setAttribute("width", "100%"); fo.setAttribute("height", "100%");

        const frame = document.createElementNS("http://www.w3.org/1999/xhtml", "iframe");
        frame.setAttribute("style", "width:100%;height:100%;border:0;display:block");
        frame.setAttribute("allow", "fullscreen;autoplay;pointer-lock;clipboard-write");
        frame.setAttribute("allowfullscreen", "true");
        fo.appendChild(frame);
        svg.appendChild(fo);
        frame.srcdoc = patched;   // property, not attribute — no escaping needed

        // Running from a local file with no server: the other three sources are
        // fine, LuminSDK will report 0 games. Say so once, in the console.
        if (location.protocol === "file:")
            console.warn("[N3ptune launcher] Opened from a local file, and no local server answered on 8777-8780. " +
                         "LuminSDK needs a real http origin, so it will show 0 games — run N3ptune.bat and reopen " +
                         "this launcher to get all four sources.");

        const card = document.getElementById("card");   // splash: gone once the app is in
        if (card) card.parentNode.removeChild(card);

        // The app owns the tab name (title cloaking), so mirror its title out.
        setInterval(function(){
            try {
                const d = frame.contentDocument;
                if (d && d.title && d.title !== document.title) document.title = d.title;
            } catch (e) {}
        }, 1000);

    } catch (err) {
        document.documentElement.setAttribute("class", "failed");
        st.textContent = "Failed to load — " + err;
        console.error(err);
    }
})();
